using Payments;

namespace Payments.Tests;

[TestClass]
public sealed class PaymentGatewayTests
{
    private readonly PaymentGateway _gateway;

    public PaymentGatewayTests()
    {
        _gateway = new PaymentGateway();
    }

    #region ChargeAsync Tests

    [TestMethod]
    public async Task ChargeAsync_ValidCardAndAmount_ReturnsSuccessfulResult()
    {
        // Arrange
        var cardToken = "tok_valid_visa";
        var amount = 49.99m;

        // Act
        var result = await _gateway.ChargeAsync(cardToken, amount);

        // Assert
        Assert.IsNotNull(result);
        Assert.IsTrue(result.Success);
        Assert.IsNotNull(result.ChargeId);
    }

    [TestMethod]
    public async Task ChargeAsync_ValidCard_ReturnsNonEmptyChargeId()
    {
        // Act
        var result = await _gateway.ChargeAsync("tok_valid_visa", 100m);

        // Assert
        Assert.IsNotNull(result.ChargeId);
        Assert.AreNotEqual(string.Empty, result.ChargeId);
    }

    [TestMethod]
    [DataRow(0.01)]
    [DataRow(1.00)]
    [DataRow(999.99)]
    [DataRow(10000.00)]
    public async Task ChargeAsync_VariousValidAmounts_Succeeds(double amountDouble)
    {
        // Arrange
        var amount = (decimal)amountDouble;

        // Act
        var result = await _gateway.ChargeAsync("tok_valid_visa", amount);

        // Assert
        Assert.IsTrue(result.Success);
    }

    [TestMethod]
    public async Task ChargeAsync_NullCardToken_ThrowsArgumentNullException()
    {
        await Assert.ThrowsExactlyAsync<ArgumentNullException>(
            async () => await _gateway.ChargeAsync(null!, 10m));
    }

    [TestMethod]
    public async Task ChargeAsync_EmptyCardToken_ThrowsArgumentException()
    {
        await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.ChargeAsync(string.Empty, 10m));
    }

    [TestMethod]
    [DataRow(0)]
    [DataRow(-1)]
    [DataRow(-100.50)]
    public async Task ChargeAsync_ZeroOrNegativeAmount_ThrowsArgumentOutOfRangeException(double amountDouble)
    {
        var amount = (decimal)amountDouble;

        await Assert.ThrowsExactlyAsync<ArgumentOutOfRangeException>(
            async () => await _gateway.ChargeAsync("tok_valid_visa", amount));
    }

    [TestMethod]
    public async Task ChargeAsync_DeclinedCard_ReturnsFailedResult()
    {
        // Arrange
        var declinedToken = "tok_declined";

        // Act
        var result = await _gateway.ChargeAsync(declinedToken, 50m);

        // Assert
        Assert.IsNotNull(result);
        Assert.IsFalse(result.Success);
    }

    [TestMethod]
    public async Task ChargeAsync_MultipleCalls_ReturnUniqueChargeIds()
    {
        // Act
        var result1 = await _gateway.ChargeAsync("tok_valid_visa", 10m);
        var result2 = await _gateway.ChargeAsync("tok_valid_visa", 20m);

        // Assert
        Assert.AreNotEqual(result1.ChargeId, result2.ChargeId);
    }

    #endregion

    #region RefundAsync Tests

    [TestMethod]
    public async Task RefundAsync_ValidChargeId_ReturnsSuccessfulResult()
    {
        // Arrange
        var charge = await _gateway.ChargeAsync("tok_valid_visa", 75m);

        // Act
        var refund = await _gateway.RefundAsync(charge.ChargeId);

        // Assert
        Assert.IsNotNull(refund);
        Assert.IsTrue(refund.Success);
        Assert.IsNotNull(refund.RefundId);
    }

    [TestMethod]
    public async Task RefundAsync_ValidChargeId_ReturnsNonEmptyRefundId()
    {
        // Arrange
        var charge = await _gateway.ChargeAsync("tok_valid_visa", 50m);

        // Act
        var refund = await _gateway.RefundAsync(charge.ChargeId);

        // Assert
        Assert.AreNotEqual(string.Empty, refund.RefundId);
    }

    [TestMethod]
    public async Task RefundAsync_NullChargeId_ThrowsArgumentNullException()
    {
        await Assert.ThrowsExactlyAsync<ArgumentNullException>(
            async () => await _gateway.RefundAsync(null!));
    }

    [TestMethod]
    public async Task RefundAsync_EmptyChargeId_ThrowsArgumentException()
    {
        await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.RefundAsync(string.Empty));
    }

    [TestMethod]
    public async Task RefundAsync_NonexistentChargeId_ReturnsFailedResult()
    {
        // Act
        var refund = await _gateway.RefundAsync("ch_nonexistent_12345");

        // Assert
        Assert.IsFalse(refund.Success);
    }

    [TestMethod]
    public async Task RefundAsync_AlreadyRefundedCharge_ReturnsFailedResult()
    {
        // Arrange
        var charge = await _gateway.ChargeAsync("tok_valid_visa", 100m);
        await _gateway.RefundAsync(charge.ChargeId);

        // Act - attempt second refund
        var secondRefund = await _gateway.RefundAsync(charge.ChargeId);

        // Assert
        Assert.IsFalse(secondRefund.Success);
    }

    #endregion
}

